/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const type = api.context.props.type;
    let heading = "";
    if (type === "communicationTask") {
        heading = helpers.translateSync("Manage recipients");
    } else if (type === "collaborationTask") {
        heading = helpers.translateSync("Manage participants");
    }
    return heading;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "selectedRole",
		value: {}
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let type = null,
        roles = [];
    if (api.state.selectedRecipientTypeAhead && api.state.selectedRecipientTypeAhead.type)
        type = api.state.selectedRecipientTypeAhead.type;
    if (api.state.roles && api.state.roles[type])
        roles = api.state.roles[type];
    return roles;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "allSelectedRecipients",
		value: []
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const allSelectedRecipients = api.state.allSelectedRecipients;
    const allSelectedRecipientsCount = Array.isArray(allSelectedRecipients) ? allSelectedRecipients.length : 0;
    const type = api.context.props.type;
    let recipientCountText = "";
    if (type === "communicationTask") {
        recipientCountText = helpers.translateSync("{0} recipients", allSelectedRecipientsCount);
    } else if (type === "collaborationTask") {
        recipientCountText = helpers.translateSync("{0} participants", allSelectedRecipientsCount);
    }
    return recipientCountText;
}

